if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefDelegateAddIdentity|" + aml);
}
if (!String.IsNullOrEmpty(this.getID()))
{
    throw new Exception("The replacement received an ID before default Add");
}
var output = new System.Xml.XmlDocument();
eventData.BaseAddItem(output);
var result = this.getInnovator().newItem();
result.loadAML(output.OuterXml);
if (String.IsNullOrEmpty(this.getID()) || this.getID() != result.getID())
{
    throw new Exception("BaseAdd did not retain its allocated input ID");
}
return result;

if (Environment.GetEnvironmentVariable("INNOVATOR_HARNESS_REFERENCE_CAPTURE") == "1")
{
    var aml = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes(this.ToString()));
    Console.WriteLine("HARNESS_REFERENCE_EVENT|RefInspectAddIdentity|" + aml);
}
if (!System.Text.RegularExpressions.Regex.IsMatch(this.getID(), "^[A-F0-9]{32}$"))
{
    throw new Exception("The before-hook did not receive an allocated ID");
}
this.setProperty("note", "Allocated before hook");
return this;
